import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1

    results = []

    for _ in range(T):
        S = data[index]
        P = data[index + 1]
        index += 2

        if P == S + S:
            results.append("Possible")
        else:
            results.append("Impossible")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
